package ai.xzkj.recruitment.localconnector;
import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController class LocalConnectorProductionApprovalController{private final LocalConnectorProductionApprovalService service;LocalConnectorProductionApprovalController(LocalConnectorProductionApprovalService s){service=s;}@GetMapping("/api/local-connector/production-approvals")List<ProductionApprovalResponse> list(){return service.list();}@PostMapping("/api/local-connector/production-approvals")@PreAuthorize("hasAnyRole('SYSTEM_ADMIN','RECRUITMENT_ADMIN')")ProductionApprovalResponse request(@Valid@RequestBody ProductionApprovalRequest r){return service.request(r);}@PostMapping("/api/local-connector/production-approvals/{id}/approve")@PreAuthorize("hasAnyRole('SYSTEM_ADMIN','RECRUITMENT_ADMIN')")ProductionApprovalResponse approve(@PathVariable UUID id,@Valid@RequestBody ProductionApprovalDecision r){return service.approve(id,r);}@PostMapping("/api/local-connector/production-approvals/{id}/revoke")@PreAuthorize("hasAnyRole('SYSTEM_ADMIN','RECRUITMENT_ADMIN')")ProductionApprovalResponse revoke(@PathVariable UUID id){return service.revoke(id);}@PostMapping("/api/local-connector/devices/{id}/emergency-stop")@PreAuthorize("hasAnyRole('SYSTEM_ADMIN','RECRUITMENT_ADMIN')")void stop(@PathVariable UUID id){service.emergencyStop(id);}}
